import{z as i,x as B,o as e,c as A,q as t,j as E,D as o,d as l,s as r,S as s,b as n}from"./chunks/framework.C8m1ZpeB.js";const L=JSON.parse('{"title":"Lyndon 分解","description":"","frontmatter":{"title":"Lyndon 分解","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lyndon-duval.md","filePath":"cs/lyndon-duval.md","lastUpdated":1791413859000}'),p={name:"cs/lyndon-duval.md"};function u(D,a,C,h,y,m){const d=B("Mermaid");return e(),A("div",null,[a[2]||(a[2]=t('<h1 id="lyndon-分解" tabindex="-1">Lyndon 分解 <a class="header-anchor" href="#lyndon-分解" aria-label="Permalink to &quot;Lyndon 分解&quot;">​</a></h1><div class="epigraph"><p>Lyndon 字严格小于其所有真后缀；每个串唯一分解成非增的 Lyndon 字串联，Duval 线性算出。</p><footer>—— 据 Chen, Fox and Lyndon, 1958；Duval, Factorizing Words over an Ordered Alphabet, 1983 整理</footer></div><p>上一课<a href="/cs/suffix-array-applications">后缀数组的应用</a>能取最小后缀，本课换分解视角：Lyndon 字——本原且字典序最小的旋转（等价：严格小于所有真后缀）。缺口是 Duval 分解：把 \\(s\\) 写成 \\(\\ell_1\\ge \\ell_2\\ge\\cdots\\) 的 Lyndon 串串联。与最小表示：一个 Lyndon 字的最小表示是自身。不重写 SA。后课正则回溯。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Duval 三个指针一趟扫完：候选块起点、块内游标、周期基准，逐位比较决定当前候选 Lyndon 块的去留——字符相等就推进，更大就把新字符吸收进块，更小则块定界、按其周期整段输出。每个字符进出候选块常数次，线性。应用：最小表示（最长 Lyndon 前缀相关）、最长 Lyndon 前缀、与 KMP 的 border 关系点名。</p><p>缺口是分解唯一性（Chen–Fox–Lyndon 定理），不是 SA 排序。</p><h3 id="不是随便的因子分解" tabindex="-1">不是随便的因子分解 <a class="header-anchor" href="#不是随便的因子分解" aria-label="Permalink to &quot;不是随便的因子分解&quot;">​</a></h3><p>唯一性是对给定字母序说的：换一个序，同一串的分解就不同——算法动手前必须先钉死序。也不要与数的质因子分解混名，「因子」在这里没有乘法结构。</p><p><span class="marginnote">CFL 定理 1958。Duval 1983 线性算法。后课正则是语言匹配，不是字的 Lyndon。</span></p><p><span class="marginnote">直觉类比：「Lyndon 字」像一串珠子围成环，从哪颗开始读都行，Lyndon 字是「从头读最小」的那串，且不是由更小的串重复而成。例如 &quot;aab&quot; 的三个旋转 aab、aba、baa 里它自己最小，是 Lyndon 字；&quot;abab&quot; 虽也是最小旋转，却由 &quot;ab&quot; 重复而成，不本原，不算。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Duval 用标准三指针实现，输出每个块的切点。最小旋转：对 \\(s+s\\) 做 Lyndon 分解、取跨过拼接缝（位置 \\(n\\)）的那个因子的起点，或直接用前课双指针。前提是字母必须全序——字典序没有定义，一切都无从谈起。</p>',12)),(e(),E(s,null,{default:o(()=>[r(d,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E4%B8%B2%20s%22%5D%20--%3E%20DUV%5B%22Duval%20%E4%B8%89%E6%8C%87%E9%92%88%22%5D%0A%20%20DUV%20--%3E%20LYN%5B%22%E9%9D%9E%E5%A2%9E%20Lyndon%20%E4%B8%B2%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("p",null,"字母必须全序。",-1)),a[4]||(a[4]=n("p",null,[n("span",{class:"marginnote"},'数字实例："banana" 按标准字母序分解为 "b"、"an"、"an"、"a" 四块——"b" \\(\\gt\\) "an"，块序列非增，每块各自是 Lyndon 字。注意方向别搞混：块与块之间要求「前不小于后」，块内部却要求整串小于自己的每个真后缀。')],-1)),a[5]||(a[5]=n("h2",{id:"机制",tabindex:"-1"},[l("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=n("p",null,"Lyndon 字的真后缀都更大，所以非增拼接后的整串周期与字典序结构良态：串的最小周期落在某个分解块的整周期处，分解因此成为字符串周期理论的基座。Duval 的跳跃与最小表示法同型——已经比较出的结论不重做，这是线性的来源。与 SA 接口：最长 Lyndon 后缀一类的量可以问后缀数组，但分解本身 Duval 线性即可，不必建 SA。",-1)),(e(),E(s,null,{default:o(()=>[r(d,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20CMP%5B%22%E8%AF%BB%E5%85%A5%E6%96%B0%E5%AD%97%E7%AC%A6%20c%22%5D%20--%3E%20BR%7B%22c%20%E4%B8%8E%E5%91%A8%E6%9C%9F%E5%9F%BA%E5%87%86%E4%BD%8D%E6%AF%94%E8%BE%83%22%7D%0A%20%20BR%20--%3E%7C%22%E7%9B%B8%E7%AD%89%22%7C%20ADV%5B%22%E6%B8%B8%E6%A0%87%E4%B8%8E%E5%9F%BA%E5%87%86%E5%90%8C%E6%AD%A5%E6%8E%A8%E8%BF%9B%E4%B8%80%E6%A0%BC%22%5D%0A%20%20BR%20--%3E%7C%22%E6%9B%B4%E5%A4%A7%22%7C%20ABS%5B%22%E5%B9%B6%E5%85%A5%E5%80%99%E9%80%89%E5%9D%97%2C%20%E5%91%A8%E6%9C%9F%E5%9F%BA%E5%87%86%E9%87%8D%E7%BD%AE%E5%88%B0%E5%9D%97%E9%A6%96%22%5D%0A%20%20BR%20--%3E%7C%22%E6%9B%B4%E5%B0%8F%22%7C%20CUT%5B%22%E5%80%99%E9%80%89%E5%9D%97%E5%AE%9A%E7%95%8C%22%5D%0A%20%20CUT%20--%3E%20OUT%5B%22%E6%8C%89%E5%9D%97%E6%9C%80%E5%B0%8F%E5%91%A8%E6%9C%9F%E6%95%B4%E6%AE%B5%E8%BE%93%E5%87%BA%2C%20%E4%BB%A5%20c%20%E5%BC%80%E6%96%B0%E5%9D%97%22%5D%0A%20%20ADV%20--%3E%20CMP%0A%20%20ABS%20--%3E%20CMP%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=t('<p><span class="marginnote">为什么是线性：相等或更大时，周期基准已经「预付」了信息——游标沿周期跳过去的安全性与块首一致，不必重比。每个字符最多被吸收、被切块各常数次，均摊 \\(O(1)\\)；若每次冲突都从块首重比，就退化成平方。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写项链多项式，不写 bi-infinite 序列的组合学。后课默认：Lyndon 分解线性、Duval 即标准实现。下一课正则匹配与回溯爆炸。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Lyndon 字小于真后缀；分解唯一非增。</li><li>Duval \\(O(n)\\)。</li><li>与最小表示、SA 接口，本课要分解。</li><li>出处：Chen, Fox and Lyndon, 1958；Duval, 1983。</li></ul>',5))])}const c=i(p,[["render",u]]);export{L as __pageData,c as default};
